<template></template>
<script>
//Component
import crud from '@imagina/qcrud/_components/crud'

const nitRegex = /^\d{5,10}-\d{1}$/;


export default {
  data() {
    return {
      crudId: this.$uid()
    }
  },
  computed: {
    crudData() {
      return {
        crudId: this.crudId,
        entityName: config("main.qcertificate.entityNames.trainingTypes"),
        apiRoute: 'apiRoutes.qcertificate.trainingTypes',
        permission: 'icertificate.trainingtypes',
        create: {
          title: this.$tr('icertificate.cms.newTrainingtype'),
        },
        read: {
          columns: [
            {name: 'id', label: this.$tr('isite.cms.form.id'), field: 'id', style: 'width: 50px'},
            {name: 'name', label: this.$tr('isite.cms.form.name'), field: 'name', align: 'left'},
						{
								name: 'status',
								label: this.$tr('isite.cms.form.status'),
								field: 'status',
								align: 'left'								
							},            
            {
              name: 'created_at', label: this.$tr('isite.cms.form.createdAt'), field: 'createdAt', align: 'left',
              format: val => val ? this.$trd(val) : '-',
            },
            {name: 'actions', label: this.$tr('isite.cms.form.actions'), align: 'left'},
          ],          
        },
        update: {
          title: this.$tr('icertificate.cms.updateTrainingtype'),          
        },
        delete: true,
        formLeft: {
          id: {value: ''},
          userId: {value: this.$store.state.quserAuth.userId},
          name: {
            value: '',
            type: 'input',           
						isTranslatable: true,
            props: {
              label: `${this.$tr('isite.cms.form.name')}*`,
              rules: [
                val => !!val || this.$tr('isite.cms.message.fieldRequired')
              ],
            },
          },  
					description: {
              value: '',
              type: 'html',
              columns: 'col-12',
              isTranslatable: true,
              props: {
                label: `${this.$tr('isite.cms.form.description')}*`,
                rules: [
                  val => !!val || this.$tr('isite.cms.message.fieldRequired')
                ],
              }
					},
				},       
					
          
        formRight: {},
      }
    },
    //Crud info
    crudInfo() {
      return this.$store.state.qcrudComponent.component[this.crudId] || {}
    }
  },
}
</script>
